const groups = ($input.all()[0]?.json?.data?.groups) || [];
const firing = [];
for (const g of groups) {
  for (const r of (g.rules || [])) {
    if (r.type !== 'alerting') continue;
    if (r.state !== 'firing') continue;
    const labels = r.labels || {};
    const annotations = r.annotations || {};
    const alertsArr = r.alerts || [];
    if (alertsArr.length === 0) {
      firing.push({
        alertname: r.name || labels.alertname || 'Unknown',
        severity: labels.severity || 'warning',
        instance: labels.instance || 'unknown',
        job: labels.job || 'unknown',
        summary: annotations.summary || '',
        description: annotations.description || '',
        startsAt: new Date().toISOString(),
        fingerprint: ((r.name || 'alert') + '-' + (labels.instance || 'unknown')).replace(/[^a-z0-9-]/gi, '-')
      });
    } else {
      for (const a of alertsArr) {
        const al = a.labels || {};
        firing.push({
          alertname: al.alertname || r.name || 'Unknown',
          severity: al.severity || 'warning',
          instance: al.instance || 'unknown',
          job: al.job || 'unknown',
          summary: annotations.summary || '',
          description: annotations.description || '',
          startsAt: a.activeAt || new Date().toISOString(),
          fingerprint: ((al.alertname || r.name || 'alert') + '-' + (al.instance || 'unknown')).replace(/[^a-z0-9-]/gi, '-')
        });
      }
    }
  }
}
return firing.map(a => ({ json: a }));

const alert = $('Extraer Alertas Firing').item.json;
const fp = alert.fingerprint;
const severity = alert.severity;
const alertname = alert.alertname;
const instance = alert.instance;
const job = alert.job;
let existingIssues = [];
try { const issuesNode = $('MantisBT – Buscar Issues Existentes').item.json;
  existingIssues = (issuesNode && issuesNode.issues) || []; } catch(e) { existingIssues = []; }

const isDuplicate = existingIssues.some(issue => {
  const s = (issue.summary || '');
  const isOpen = issue.status?.name !== 'closed' && issue.status?.name !== 'resolved';
  return isOpen && s.includes(fp);
});

const sumTxt = ('[ALERTA][' + String(severity).toUpperCase() + '] ' + alertname + ' - ' + instance + ' [' + fp + ']').slice(0, 255);
const desc = '## Alerta Prometheus\n\n'
  + '**Nombre:** ' + alertname + '\n'
  + '**Severidad:** ' + severity + '\n'
  + '**Instancia:** ' + instance + '\n'
  + '**Job:** ' + String(job || '') + '\n\n'
  + '### Resumen\n' + String(alert.summary || '') + '\n\n'
  + '### Descripcion\n' + String(alert.description || '') + '\n\n'
  + '### Inicio\n' + String(alert.startsAt || '') + '\n\n'
  + '*automatizado por n8n - WF Alertas desde Prometheus*';

return {
  json: Object.assign({}, $input.item.json, {
    isDuplicate,
    summary: sumTxt,
    description: desc,
    fingerprint: fp,
    severity,
    alertname,
    instance,
    job
  })
};

const issue = $input.item.json;
const issueId = issue.issue?.id || issue.id || 'desconocido';
const summary = issue.issue?.summary || issue.summary || 'sin resumen';
console.log('[WF1] Issue creado en MantisBT: ID=' + issueId + ' | ' + summary);
return { json: { resultado: 'issue_creado', issueId, summary, timestamp: new Date().toISOString() } };
